/**
 * front-yards.js — the 1904 district's front yards: foundation shrubs, beds, creeper (T-3203).
 *
 * WHY. The owner, 2026-10-27: *"plants in front of the houses they seem to be missing flora
 * on the property"*. Every house lot was bare sward from its lot line to its front wall,
 * where every picture of the street shows a planted front yard.
 *
 * WHAT IT DRAWS, from `data/front_yards/<scene>.json` (generated by
 * tools/plant_prairie_1904_front_yards.py from the street grid's lots and the houses' own
 * baked models, so nothing stands on a stoop, a fence, a walk or a door's way). The lawn is
 * the ground's own: the 1904 field already lays a green, shadowed sward on every lot, and a
 * flat overlay drawn over it read worse than the sward it covered, so none is drawn here.
 *
 *   shrubs    foundation shrubs along each front and the first metres of its sides, in
 *             three habits (clipped evergreen, flowering mound, tall lilac-like), each
 *             turned, sized and toned on its own, instanced at two levels by distance;
 *   beds      one to three low beds cut in the lawn, a raised edge of loam planted with
 *             bedding (geranium red, white and pink, yellow and orange, coleus), the plants
 *             drawn only near the eye;
 *   creeper   ivy up the walls a picture shows it on (Pullman's front, 1912's).
 *
 * WHAT IS EVIDENCE. Pullman's ivy and its shrub border along 18th Street are in the Detroit
 * Publishing views and are attested; 1912's ivy is in a later photograph, so inferred; the
 * rest is the district's common treatment, reconstructed (docs/LIBERTIES.md
 * L-prairie-front-yards-3203). Each instance carries its tier, so the confidence view shows
 * which is which, and a click on a shrub or a bed says so in words.
 *
 * A scene that does not list `front_yards` hands this no data base and it draws nothing; a
 * failed fetch draws nothing and records a problem.
 */

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { FOLIAGE, patchFoliage, patchSeason } from './season.js';

const CONF = { attested: 0, inferred: 0.5, reconstructed: 1 };
const BED_LIFT_M = 0.06;
/** Rings, metres from the eye: the full shrub inside `near`, a plain one to `far`; the bed
 *  plants inside `plants`. */
const RINGS = {
  full: { near: 45, far: 230, plants: 40, shadow: true },
  balanced: { near: 35, far: 180, plants: 30, shadow: true },
  light: { near: 20, far: 110, plants: 16, shadow: false },
};
const REDEAL_M = 3;
/** Each habit's leaf, dark to light (a shrub's `tone` picks between them). */
const LEAF = {
  clipped: [0x24391c, 0x3a5528],
  mound: [0x3c5a26, 0x5f7d34],
  tall: [0x33502a, 0x4f6c37],
  creeper: [0x3d5f2a, 0x648a3c],
};
/** Bedding: [bloom colours], with foliage clumps between. */
const BEDDING = [
  [0xb3261e, 0xc8332a, 0x9e1f1a],        // scarlet geraniums
  [0xeeeae0, 0xe7a9b8, 0xd8798f],        // white and pink
  [0xe8b923, 0xe08a1e, 0xf0d24a],        // marigold and nasturtium
  [0x7d2a4a, 0xa8432d, 0x8f9a2c],        // coleus
];
const LOAM = 0x4a3826;

async function getJSON(url) {
  const res = await fetch(url, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} — ${url}`);
  return res.json();
}

/** A small deterministic hash, so a re-load grows the same yard. */
function hash(a, b = 0) {
  let h = Math.imul((a * 73856093) ^ (b * 19349663), 0x27d4eb2d) >>> 0;
  h ^= h >>> 15; h = Math.imul(h, 0x2c1b3c6d) >>> 0; h ^= h >>> 12;
  return (h >>> 0) / 4294967296;
}

/* -------------------------------------------------------------------------- */
/* the plants' shapes                                                          */
/* -------------------------------------------------------------------------- */

/** Lumps of leaf merged into one habit, fitted to x,z in [-1, 1] and y in [0, 1], with a
 *  vertex shade darker toward the inside and the foot (the light a bush lets in). */
function habit(lumps, detail, rough) {
  const parts = lumps.map(([x, y, z, r, sy], i) => {
    const g = new THREE.IcosahedronGeometry(r, detail);
    const p = g.attributes.position;
    for (let k = 0; k < p.count; k += 1) {
      const vx = p.getX(k); const vy = p.getY(k); const vz = p.getZ(k);
      const n = 1 + rough * (hash(Math.round(vx * 97) + i * 7, Math.round(vy * 89 + vz * 61)) - 0.5);
      p.setXYZ(k, x + vx * n, y + vy * n * sy, z + vz * n);
    }
    g.deleteAttribute('uv');
    return g;
  });
  const geo = mergeGeometries(parts, false);
  for (const g of parts) g.dispose();
  geo.computeBoundingBox();
  const b = geo.boundingBox;
  const sx = 2 / (b.max.x - b.min.x); const sz = 2 / (b.max.z - b.min.z); const sy = 1 / (b.max.y - b.min.y);
  const cx = (b.max.x + b.min.x) / 2; const cz = (b.max.z + b.min.z) / 2;
  const p = geo.attributes.position;
  const col = new Float32Array(p.count * 3);
  for (let k = 0; k < p.count; k += 1) {
    const x = (p.getX(k) - cx) * sx; const y = (p.getY(k) - b.min.y) * sy; const z = (p.getZ(k) - cz) * sz;
    p.setXYZ(k, x, y, z);
    const out = Math.min(1, Math.hypot(x, z));
    const shade = 0.55 + 0.3 * y + 0.15 * out + 0.12 * (hash(k, 3) - 0.5);
    col[k * 3] = shade; col[k * 3 + 1] = shade; col[k * 3 + 2] = shade;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  geo.computeVertexNormals();
  geo.computeBoundingSphere();
  return geo;
}

/** Each habit near the eye; past the near ring every habit is one rough lump (20 triangles),
 *  which at that distance is what a bush is. */
const HABITS = {
  clipped: () => habit([[0, 0.5, 0, 1, 0.62]], 1, 0.06),
  mound: () => habit([[0, 0.55, 0, 0.75, 0.8], [0.55, 0.42, 0.2, 0.55, 0.85], [-0.5, 0.4, 0.25, 0.55, 0.8],
    [0.1, 0.45, -0.5, 0.55, 0.85]], 1, 0.3),
  tall: () => habit([[0, 0.35, 0, 0.55, 1], [0.35, 0.8, 0.2, 0.6, 1], [-0.35, 0.85, -0.1, 0.6, 1],
    [0.05, 1.2, 0.05, 0.62, 0.9]], 1, 0.3),
  creeper: () => habit([[0, 0.5, 0, 0.8, 1], [0.55, 0.45, 0, 0.55, 1.1], [-0.55, 0.55, 0, 0.55, 1.1]], 1, 0.35),
  far: () => habit([[0, 0.5, 0, 1, 0.85]], 0, 0.2),
  plant: () => habit([[0, 0.5, 0, 1, 0.9], [0.5, 0.45, 0.3, 0.6, 0.9]], 0, 0.25),
};

/* -------------------------------------------------------------------------- */
/* the cards                                                                   */
/* -------------------------------------------------------------------------- */

function lotWhere(lot) {
  const a = lot.addresses?.length ? `${lot.addresses[0]} ` : '';
  const street = { prairie: 'Prairie Avenue', indiana: 'Indiana Avenue', calumet: 'Calumet Avenue' }[lot.street]
    ?? `East ${String(lot.street).replace(/^e/, '')} Street`;
  return `${a}${street}`;
}

function plantCard(hit, doc) {
  const { lot, kind, grade } = hit;
  const where = lotWhere(lot);
  const pictured = lot.pictured_notes ?? {};
  const note = kind === 'creeper' ? pictured.creeper?.note
    : (grade === 'attested' ? pictured.border?.note : null);
  const name = { shrub: `A ${doc.forms?.[hit.form]?.name ?? 'shrub'} in the front yard`,
    bed: 'A flower bed in the front lawn', creeper: 'Ivy on the house front' }[kind];
  const what = kind === 'shrub' ? (doc.forms?.[hit.form]?.note ?? '')
    : kind === 'bed' ? (doc.beds?.[hit.bedKind] ?? '') : 'ivy or Virginia creeper on the wall';
  return {
    id: `front-yard.${lot.parcel}.${kind}.${hit.index}`,
    sidecar: {
      name,
      phase: null,
      change_note: grade === 'reconstructed'
        ? `The front yard at ${where}: a mown lawn, shrubs along the house and a few low beds. The pictures `
          + 'of the district show kept front yards like this; nothing records what grew on this lot, so this '
          + 'planting is our reconstruction.'
        : `${note ?? ''}`.trim(),
      placement: {
        symbolic_location: where,
        position_confidence: grade,
        position_sources: grade === 'reconstructed' ? [] : (lot.pictured?.sources ?? []),
        position_note: grade === 'reconstructed' ? (doc.placement?.note ?? '') : (note ?? ''),
      },
      attributes: {
        planting: {
          value: what, confidence: grade, sources: grade === 'reconstructed' ? [] : (lot.pictured?.sources ?? []),
          note: grade === 'reconstructed' ? `Reconstructed: ${doc.liberty ?? ''}`.trim() : (note ?? ''),
        },
      },
      citations: [],
      research_note: `Lot ${lot.parcel} of data/front_yards/1904.json (T-3203). ${doc.liberty ?? ''}`.trim(),
    },
  };
}

/* -------------------------------------------------------------------------- */
/* the layer                                                                   */
/* -------------------------------------------------------------------------- */

/**
 * @param {object} o dataBase (data/ root, or null when the scene does not list the layer) ·
 *   sceneId · terrain · confidence · problems · detail · levelAt (the street grid's drop
 *   below the field at a point)
 */
export async function createFrontYards({
  dataBase, sceneId, terrain, confidence = null, problems = [], detail = 'full', levelAt = null,
} = {}) {
  const group = new THREE.Group();
  group.name = 'front-yards';
  const stats = { lots: 0, shrubs: 0, beds: 0, creeper: 0, near: 0, far: 0, plants: 0,
    triangles: 0, drawCalls: 0, detail };
  const out = {
    group, stats, records: [],
    pickAt: () => null, update() {}, setDetail() {}, settle() {}, cardFor: () => null, dispose() {},
  };
  if (!dataBase || !terrain) return out;
  let doc;
  try {
    doc = await getJSON(new URL(`front_yards/${sceneId}.json`, dataBase));
  } catch (err) {
    problems.push(`front yards: ${err.message} — no front-yard planting is drawn`);
    return out;
  }
  const lots = doc.lots ?? [];
  out.records = lots;
  stats.lots = lots.length;
  if (!lots.length) return out;
  const groundAt = (e, n) => terrain.surfaceHeight(e, n) + (levelAt?.(e, n) ?? 0);
  const disposers = [];

  /* ---- the beds' loam: one mesh -------------------------------------------- */
  const beds = [];
  {
    const pos = []; const conf = [];
    for (const lot of lots) {
      for (const [i, b] of lot.beds.entries()) {
        const [e, n, a, w, heading, kind, palette] = b;
        const h = (heading * Math.PI) / 180;
        const ax = [Math.sin(h), Math.cos(h)]; const ay = [Math.cos(h), -Math.sin(h)];
        const ring = [];
        const SEG = kind === 'border' ? 4 : 18;
        for (let k = 0; k < SEG; k += 1) {
          let u; let v;
          if (kind === 'border') {
            const t = [[-1, -1], [1, -1], [1, 1], [-1, 1]][k]; u = t[0] * a; v = t[1] * w;
          } else {
            const t = (k / SEG) * Math.PI * 2; u = Math.cos(t) * a; v = Math.sin(t) * w;
          }
          ring.push([e + ax[0] * u + ay[0] * v, n + ax[1] * u + ay[1] * v]);
        }
        const y0 = groundAt(e, n) + BED_LIFT_M;
        for (let k = 0; k < SEG; k += 1) {
          const p = ring[k]; const q = ring[(k + 1) % SEG];
          pos.push(e, y0, -n, q[0], y0, -q[1], p[0], y0, -p[1]);
          // the cut edge, down to the lawn
          const yb = y0 - BED_LIFT_M;
          pos.push(p[0], y0, -p[1], q[0], y0, -q[1], q[0], yb, -q[1], p[0], y0, -p[1], q[0], yb, -q[1], p[0], yb, -p[1]);
          for (let z = 0; z < 9; z += 1) conf.push(CONF.reconstructed);
        }
        beds.push({ lot, i, e, n, a, w, ax, ay, kind, palette, y: y0, grade: 'reconstructed' });
      }
    }
    if (pos.length) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
      geo.setAttribute('_confidence', new THREE.Float32BufferAttribute(conf, 1));
      geo.computeVertexNormals();
      const mat = new THREE.MeshStandardMaterial({ color: LOAM, roughness: 1, metalness: 0, side: THREE.DoubleSide });
      mat.name = 'front-yards-loam';
      confidence?.patch(mat);
      patchSeason(mat, 0.6);
      const mesh = new THREE.Mesh(geo, mat);
      mesh.name = 'front-yards-beds';
      mesh.receiveShadow = true;
      group.add(mesh);
      disposers.push(() => { geo.dispose(); mat.dispose(); });
    }
  }
  stats.beds = beds.length;

  /* ---- what stands: shrubs, creeper, bedding ------------------------------ */
  const up = new THREE.Vector3(0, 1, 0);
  const placed = [];   // { x, z, y, q, sx, sy, sz, form, colour, conf, lot, kind, index }
  const tmp = new THREE.Color();
  const shade = (pair, t) => tmp.set(pair[0]).lerp(new THREE.Color(pair[1]), t).clone();
  for (const lot of lots) {
    for (const [i, s] of lot.shrubs.entries()) {
      const [e, n, r, h, form, tone, grade] = s;
      const yaw = hash(Math.round(e * 10), Math.round(n * 10)) * Math.PI * 2;
      placed.push({ x: e, z: -n, y: groundAt(e, n), q: new THREE.Quaternion().setFromAxisAngle(up, yaw),
        sx: r, sy: h, sz: r * (0.85 + 0.3 * hash(i, 9)), form, colour: shade(LEAF[form] ?? LEAF.mound, tone),
        conf: CONF[grade ?? lot.grade] ?? 1, grade: grade ?? lot.grade, lot, kind: 'shrub', index: i });
    }
    const cg = lot.pictured_notes?.creeper?.grade ?? 'reconstructed';
    for (const [i, c] of lot.creeper.entries()) {
      const [e, n, facing, w, h] = c;
      const f = (facing * Math.PI) / 180;
      // a little back toward the wall it climbs, its thin side against it
      const ce = e - Math.sin(f) * 0.12; const cn = n - Math.cos(f) * 0.12;
      const q = new THREE.Quaternion().setFromAxisAngle(up, -f);
      const y0 = groundAt(ce, cn);
      // a mat up the wall: broad overlapping pieces, each a little off the line of the last,
      // so the patches along a front run together and their tops are ragged
      const pieces = Math.max(1, Math.round(h / 1.4));
      const along = [Math.cos(f), -Math.sin(f)];   // the wall's line, in (e, n)
      for (let k = 0; k < pieces; k += 1) {
        const t = hash(i * 13 + k, 5);
        const off = (hash(i * 7 + k, 11) - 0.5) * 0.5;
        const top = k === pieces - 1;
        placed.push({ x: ce + along[0] * off, z: -(cn + along[1] * off), y: y0 + k * (h / pieces) - 0.15, q,
          sx: (0.7 + w * 0.55) * (top ? 0.8 - 0.3 * t : 1 - 0.15 * t), sy: (h / pieces) * 1.45, sz: 0.1,
          form: 'creeper', colour: shade(LEAF.creeper, t),
          conf: CONF[cg] ?? 1, grade: cg, lot, kind: 'creeper', index: i, creeper: true });
      }
      stats.creeper += 1;
    }
  }
  stats.shrubs = placed.filter((p) => p.kind === 'shrub').length;

  const mats = {};
  const matFor = (key) => {
    if (mats[key]) return mats[key];
    const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.88, metalness: 0 });
    m.name = `front-yards-${key}`;
    confidence?.patch(m);
    // A clipped evergreen keeps its leaf all year; the rest turn and fall with the Season.
    if (key !== 'clipped') patchFoliage(m, key === 'plant' ? FOLIAGE.grass : FOLIAGE.leaf);
    mats[key] = m;
    return m;
  };
  const meshes = [];
  const geos = [];
  const addMesh = (name, geo, mat, max, level, filter) => {
    geo.setAttribute('_confidence', new THREE.InstancedBufferAttribute(new Float32Array(max), 1));
    const mesh = new THREE.InstancedMesh(geo, mat, max);
    mesh.name = `front-yards-${name}-${level}`;
    mesh.count = 0;
    mesh.receiveShadow = true;
    mesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(max * 3), 3);
    mesh.userData = { level, filter, max };
    group.add(mesh);
    meshes.push(mesh);
    geos.push(geo);
  };
  for (const form of ['clipped', 'mound', 'tall', 'creeper']) {
    const filter = (p) => p.form === form;
    const max = placed.filter(filter).length;
    if (!max) continue;
    addMesh(form, HABITS[form](), matFor(form), max, 'near', filter);
    addMesh(form, HABITS.far(), matFor(form), max, 'far', filter);
  }

  // The bedding: small plants on a jittered grid inside each bed, every few a bloom.
  const plants = [];
  for (const b of beds) {
    const pal = BEDDING[b.palette % BEDDING.length];
    const step = 0.3;
    for (let u = -b.a + step / 2; u < b.a; u += step) {
      for (let v = -b.w + step / 2; v < b.w; v += step) {
        const j = hash(Math.round((b.e + u) * 37), Math.round((b.n + v) * 41));
        const uu = u + (j - 0.5) * 0.12; const vv = v + (hash(j * 1e6, 2) - 0.5) * 0.12;
        if (b.kind !== 'border' && (uu * uu) / (b.a * b.a) + (vv * vv) / (b.w * b.w) > 0.8) continue;
        if (b.kind === 'border' && (Math.abs(uu) > b.a - 0.1 || Math.abs(vv) > b.w - 0.08)) continue;
        const bloom = j < 0.72;
        const e = b.e + b.ax[0] * uu + b.ay[0] * vv; const n = b.n + b.ax[1] * uu + b.ay[1] * vv;
        const colour = bloom ? new THREE.Color(pal[Math.floor(j * 97) % pal.length]) : new THREE.Color(0x3f6127);
        plants.push({ x: e, z: -n, y: b.y - 0.02, q: new THREE.Quaternion().setFromAxisAngle(up, j * 6.28),
          sx: 0.13 + 0.05 * j, sy: 0.26 + 0.14 * j, sz: 0.13 + 0.05 * j, colour, conf: CONF.reconstructed, bed: b });
      }
    }
  }
  stats.plantsTotal = plants.length;
  if (plants.length) addMesh('bedding', HABITS.plant(), matFor('plant'), plants.length, 'plants', null);

  /* ---- the deal: what each level draws, from where the eye is ------------- */
  let tier = RINGS[detail] ? detail : 'full';
  const last = new THREE.Vector3(Infinity, 0, 0);
  const m4 = new THREE.Matrix4(); const p3 = new THREE.Vector3(); const s3 = new THREE.Vector3();
  const deal = (eye) => {
    const ring = RINGS[tier];
    let triangles = 0; let calls = 0; let nearN = 0; let farN = 0; let plantN = 0;
    for (const mesh of meshes) {
      const { level, filter } = mesh.userData;
      const conf = mesh.geometry.getAttribute('_confidence');
      const list = level === 'plants' ? plants : placed;
      let k = 0;
      for (const p of list) {
        if (filter && !filter(p)) continue;
        const d = Math.hypot(p.x - eye.x, p.z - eye.z);
        const lvl = level === 'plants' ? (d <= ring.plants ? 'plants' : null)
          : (d <= ring.near ? 'near' : (d <= ring.far ? 'far' : null));
        if (lvl !== level) continue;
        p3.set(p.x, p.y, p.z);
        s3.set(p.sx, p.sy, p.sz);
        mesh.setMatrixAt(k, m4.compose(p3, p.q, s3));
        mesh.setColorAt(k, p.colour);
        conf.array[k] = p.conf;
        k += 1;
      }
      mesh.count = k;
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
      conf.needsUpdate = true;
      mesh.visible = k > 0;
      mesh.castShadow = level === 'near' && ring.shadow;
      if (k) {
        mesh.computeBoundingSphere();
        calls += 1;
        triangles += k * (mesh.geometry.index ? mesh.geometry.index.count : mesh.geometry.attributes.position.count) / 3;
        if (level === 'near') nearN += k; else if (level === 'far') farN += k; else plantN += k;
      }
    }
    stats.near = nearN; stats.far = farN; stats.plants = plantN;
    stats.triangles = triangles; stats.drawCalls = calls + 1; stats.detail = tier;
    last.copy(eye);
  };

  out.update = (_dt, camera = null) => {
    if (!camera) return;
    const eye = camera.position;
    if (Math.hypot(eye.x - last.x, eye.z - last.z) >= REDEAL_M) deal(eye);
  };
  out.setDetail = (d) => {
    if (!RINGS[d] || d === tier) return;
    tier = d;
    if (Number.isFinite(last.x)) deal(last.clone());
  };
  /** Deal now, from this eye (a still frame for a reading or a shot). */
  out.settle = (camera) => { if (camera) deal(camera.position.clone()); };

  /* ---- picks: a shrub, an ivy patch or a bed under the crosshair --------- */
  const ray = new THREE.Raycaster();
  out.pickAt = (ndc, camera) => {
    if (!camera || !group.visible) return null;
    ray.setFromCamera(ndc ?? new THREE.Vector2(0, 0), camera);
    const o = ray.ray.origin; const d = ray.ray.direction;
    let best = null;
    const sphere = new THREE.Sphere(); const hitP = new THREE.Vector3();
    const near = RINGS[tier].near;
    for (const p of placed) {
      if (Math.hypot(p.x - o.x, p.z - o.z) > near) continue;
      sphere.center.set(p.x, p.y + p.sy * 0.5, p.z);
      sphere.radius = Math.max(p.sx, p.sy * 0.5) * 0.9;
      if (!ray.ray.intersectSphere(sphere, hitP)) continue;
      const t = hitP.distanceTo(o);
      if (!best || t < best.distance) best = { hit: p, distance: t, point: hitP.clone() };
    }
    for (const b of beds) {
      if (Math.hypot(b.e - o.x, -b.n - o.z) > near || Math.abs(d.y) < 1e-6) continue;
      const t = (b.y + 0.1 - o.y) / d.y;
      if (!(t > 0)) continue;
      const x = o.x + d.x * t - b.e; const zN = -(o.z + d.z * t) - b.n;
      const u = x * b.ax[0] + zN * b.ax[1]; const v = x * b.ay[0] + zN * b.ay[1];
      const inside = b.kind === 'border' ? Math.abs(u) <= b.a && Math.abs(v) <= b.w
        : (u * u) / (b.a * b.a) + (v * v) / (b.w * b.w) <= 1;
      if (inside && (!best || t < best.distance)) {
        best = { hit: { lot: b.lot, kind: 'bed', index: b.i, bedKind: b.kind, grade: b.grade },
          distance: t, point: new THREE.Vector3(o.x + d.x * t, b.y, o.z + d.z * t) };
      }
    }
    if (!best) return null;
    const record = plantCard(best.hit, doc);
    return { id: record.id, record, point: best.point, distance: best.distance };
  };
  out.cardFor = (id) => {
    const m = /^front-yard\.(.+)\.(shrub|bed|creeper)\.(\d+)$/.exec(id ?? '');
    if (!m) return null;
    const lot = lots.find((l) => l.parcel === m[1]);
    if (!lot) return null;
    const i = Number(m[3]);
    const s = lot.shrubs[i];
    const hit = m[2] === 'shrub' && s ? { lot, kind: 'shrub', index: i, form: s[4], grade: s[6] ?? lot.grade }
      : m[2] === 'bed' && lot.beds[i] ? { lot, kind: 'bed', index: i, bedKind: lot.beds[i][5], grade: lot.grade }
        : m[2] === 'creeper' ? { lot, kind: 'creeper', index: i, grade: lot.pictured_notes?.creeper?.grade ?? lot.grade }
          : null;
    return hit ? plantCard(hit, doc) : null;
  };
  out.dispose = () => {
    for (const g of geos) g.dispose();
    for (const m of Object.values(mats)) m.dispose();
    for (const f of disposers) f();
  };
  return out;
}
